import Tooltip from "@marko-ui/shadcn/ui/tooltip/tooltip.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Kbd from "@marko-ui/shadcn/ui/kbd/kbd.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

<Tooltip>
  <@trigger|props|>
    <Button type="button" ...props variant="outline" size="icon-sm" aria-label="Save Changes">
      <Icon name="SaveIcon"/>
    </Button>
  </@trigger>
  Save Changes <Kbd>S</Kbd>
</Tooltip>
